import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;

public final class PracticedContentGameTests {
    public static void reloadBindingInvariant(GameTestHelper h){
        try{
            Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"copper_pickaxe\":{\"ticks\":1200,\"practice\":30}}").getAsJsonObject());
            var active=Production.RECIPES;boolean rejected=false;
            try{Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"copper_pickaxe\":{\"second\":\"\"}}").getAsJsonObject());}catch(IllegalArgumentException expected){rejected=true;}
            h.assertTrue(rejected&&Production.RECIPES==active&&Production.RECIPES.get("copper_pickaxe").ticks()==1200&&Production.RECIPES.get("copper_pickaxe").practice()==30,"Reload cannot remove an equipment binding or partially replace active recipes; numeric duration/practice tuning stays allowed");
            rejected=false;try{Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"forged_iron_chestplate\":{\"second\":\"minecraft:stick\"}}").getAsJsonObject());}catch(IllegalArgumentException expected){rejected=true;}
            h.assertTrue(rejected&&Production.RECIPES==active,"Mandatory armour rivets cannot be replaced by an unrelated secondary ingredient");
            rejected=false;try{Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"forged_iron_chestplate\":{\"secondCount\":1}}").getAsJsonObject());}catch(IllegalArgumentException expected){rejected=true;}
            h.assertTrue(rejected&&Production.RECIPES==active,"Reload cannot remove one of the two mandatory armour rivets");
        }finally{Production.reloadDefinitions(new com.google.gson.JsonObject());}h.succeed();
    }
    public static void reloadBlankStageInvariant(GameTestHelper h){
        try{
            Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"forge_copper_pickaxe_blank\":{\"ticks\":800,\"practice\":0}}").getAsJsonObject());
            var active=Production.RECIPES;boolean rejected=false;
            try{Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"forge_copper_pickaxe_blank\":{\"station\":\"kiln\",\"forge\":false,\"manual\":false,\"heated\":false,\"skill\":\"none\",\"practice\":0}}").getAsJsonObject());}catch(IllegalArgumentException expected){rejected=true;}
            h.assertTrue(rejected&&Production.RECIPES==active&&Production.RECIPES.get("forge_copper_pickaxe_blank").ticks()==800&&Production.RECIPES.get("forge_copper_pickaxe_blank").practice()==0,"Known equipment blank formation must remain heated manual forge work without forbidding numeric time/practice tuning");
        }finally{Production.reloadDefinitions(new com.google.gson.JsonObject());}h.succeed();
    }

    public static void jarCapacities(GameTestHelper h){var actor=actor(h,1,0);h.setBlock(2,2,1,Blocks.WATER);String[] qualities={"rough","standard","fine"};for(int i=0;i<3;i++){var pot=new ItemStack(SurvivalContent.item("fired_pot"));var data=ItemAging.data(pot);data.putString("potQuality",qualities[i]);ItemAging.data(pot,data);actor.setItemInHand(InteractionHand.MAIN_HAND,pot);Pottery.action(actor,"fill");h.assertTrue(Pottery.waterUnits(pot)==i+2,"Jar quality must bound actual water portions");for(int j=0;j<i+2;j++)h.assertTrue(Pottery.consumeWater(pot),"Every stored portion must be consumable once");h.assertTrue(!Pottery.consumeWater(pot),"A depleted jar cannot mint extra water");for(int j=0;j<i+3;j++){actor.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.BEEF));Pottery.action(actor,"store");}h.assertTrue(pot.get(DataComponents.CONTAINER).size()==i+2&&actor.getOffhandItem().getCount()==1,"Quality must limit real stored food slots without consuming a rejected stack");h.assertTrue(Math.abs(1/Pottery.preservationRate(pot)-new double[]{2,4,6}[i])<.001,"Rough/standard/fine preservation must be exactly2x/4x/6x");}actor.discard();h.succeed();}
    public static void noviceRivetsPractice(GameTestHelper h){Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"copper_rivets\":{\"ticks\":1}}").getAsJsonObject());try{var actor=actor(h,1,0);var forge=station(h,"forge",1);forge.fuel=8000;actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.COPPER_INGOT));h.assertTrue(Production.start(actor,forge,"copper_rivets").startsWith("Started"),"Useful novice copper working must avoid the smith20 bootstrap lock");h.assertTrue(SurvivalApi.state(actor).skills.experience(SkillSet.Skill.SMITHING)==0,"Starting a practice job cannot grant experience");h.runAfterDelay(60,()->{try{h.assertTrue(forge.output.is(SurvivalContent.item("metal_rivet"))&&forge.output.getCount()==4&&actor.getMainHandItem().isEmpty(),"Novice practice must consume a real ingot and produce useful armour rivets");h.assertTrue(SurvivalApi.state(actor).skills.level(SkillSet.Skill.SMITHING)==0&&SurvivalApi.state(actor).skills.experience(SkillSet.Skill.SMITHING)>0,"Useful completed work grants bounded novice learning, not instant professional competence");actor.discard();h.succeed();}finally{Production.reloadDefinitions(new com.google.gson.JsonObject());}});}catch(RuntimeException|Error failure){Production.reloadDefinitions(new com.google.gson.JsonObject());throw failure;}}
    public static void fullMetalChain(GameTestHelper h){Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"smelt_copper\":{\"count\":3,\"amount\":3,\"ticks\":1},\"forge_copper_pickaxe_blank\":{\"ticks\":1},\"copper_pickaxe\":{\"ticks\":1}}").getAsJsonObject());try{var actor=actor(h,2,0);var body=SurvivalApi.state(actor);body.skills.setLevel(SkillSet.Skill.SMITHING,4);SurvivalApi.save(actor,body);var bloomery=station(h,"bloomery",1);var forge=station(h,"forge",3);var anvil=station(h,"anvil",4);bloomery.fuel=8000;forge.fuel=8000;actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SurvivalContent.item("roasted_copper"),3));h.assertTrue(!Production.start(actor,forge,"smelt_copper").startsWith("Started")&&actor.getMainHandItem().getCount()==3,"Forge cannot replace the real bloomery smelting step");h.assertTrue(Production.start(actor,bloomery,"smelt_copper").startsWith("Started"),"Real roasted ore must enter a bloomery");bloomery.advance(h.getLevel(),SurvivalApi.calendar(h.getLevel())+1);h.assertTrue(bloomery.output.is(Items.COPPER_INGOT)&&bloomery.output.getCount()==3,"Bloomery must consume ore and create exactly its smelted ingots");actor.setItemInHand(InteractionHand.MAIN_HAND,bloomery.output);bloomery.output=ItemStack.EMPTY;h.assertTrue(Production.start(actor,forge,"forge_copper_pickaxe_blank").startsWith("Started"),"Smelted ingots must enter heated blank formation");h.runAfterDelay(21,()->{try{h.assertTrue(forge.output.is(SurvivalContent.item("copper_pickaxe_blank"))&&forge.output.getCount()==1,"Forge must produce a real unfinished blank, not a finished tool");actor.setItemInHand(InteractionHand.MAIN_HAND,forge.output);forge.output=ItemStack.EMPTY;actor.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(SurvivalContent.item("cordage")));Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"copper_pickaxe\":{\"ticks\":1}}").getAsJsonObject());h.assertTrue(Production.start(actor,anvil,"copper_pickaxe").startsWith("Started"),"A trained smith must finish the actual blank at an anvil");h.runAfterDelay(21,()->{try{h.assertTrue(anvil.output.is(SurvivalContent.item("copper_pickaxe"))&&anvil.output.getCount()==1&&anvil.input.isEmpty()&&anvil.secondary.isEmpty()&&anvil.fuel==0,"Only completed anvil work may consume blank/binding and create the finished useful tool");actor.discard();h.succeed();}finally{Production.reloadDefinitions(new com.google.gson.JsonObject());}});}catch(RuntimeException|Error failure){Production.reloadDefinitions(new com.google.gson.JsonObject());throw failure;}});}catch(RuntimeException|Error failure){Production.reloadDefinitions(new com.google.gson.JsonObject());throw failure;}}
    private static LivingEntity actor(GameTestHelper h,int x,int potteryXp){h.setBlock(x,1,1,Blocks.STONE);var actor=h.spawn(EntityTypes.VILLAGER,new BlockPos(x,2,1));actor.setNoAi(true);SurvivalApi.enroll(actor);var body=SurvivalApi.state(actor);body.skills.setLevel(SkillSet.Skill.POTTERY,(int)(2*Math.sqrt(potteryXp)/5));SurvivalApi.save(actor,body);return actor;}
    private static WorkstationEntity station(GameTestHelper h,String id,int x){var block=BuiltInRegistries.BLOCK.getValue(Identifier.fromNamespaceAndPath(SurvivalContent.MODID,id));h.assertTrue(block instanceof WorkstationBlock,"A real "+id+" workstation must be registered");var pos=h.absolutePos(new BlockPos(x,1,2));h.getLevel().setBlock(pos,block.defaultBlockState(),3);return (WorkstationEntity)h.getLevel().getBlockEntity(pos);}
    public static void clayPotQuality(GameTestHelper h){
        Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"fire_pot\":{\"ticks\":20}}").getAsJsonObject());
        try{
            var novice=actor(h,1,0);var standard=actor(h,3,225);var expert=actor(h,5,1600);var actors=new LivingEntity[]{novice,standard,expert};var kilns=new WorkstationEntity[3];double[] startingXp={0,21000,157000};
            for(int i=0;i<3;i++){var kiln=station(h,"kiln",1+i*2);kilns[i]=kiln;kiln.fuel=8000;actors[i].setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Blocks.CLAY,2));String start=Production.start(actors[i],kiln,"fire_pot");h.assertTrue(start.startsWith("Started"),"One real clay block plus a fueled kiln must start a pottery job");h.assertTrue(actors[i].getMainHandItem().getCount()==1&&kiln.output.isEmpty(),"Pottery must consume one clay block and wait for loaded manual completion");}
            var saved=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());kilns[0].saveWithoutMetadata(saved);kilns[0].loadCustomOnly(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),saved.buildResult()));
            h.runAfterDelay(80,()->{
                try{String[] quality={"rough","standard","fine"};for(int i=0;i<3;i++){h.assertTrue(kilns[i].output.is(SurvivalContent.item("fired_pot")),"Tended pottery must actually complete after its loaded work interval");h.assertTrue(ItemAging.data(kilns[i].output).getStringOr("potQuality","").equals(quality[i]),"Effective pottery score must determine "+quality[i]+" jar quality");h.assertTrue(SurvivalApi.state(actors[i]).skills.lastPracticeTick(SkillSet.Skill.POTTERY)>0&&SurvivalApi.state(actors[i]).skills.experience(SkillSet.Skill.POTTERY)>startingXp[i]-3,"Completed useful pottery awards learning alongside bounded expert decay");double earned=SurvivalApi.state(actors[i]).skills.experience(SkillSet.Skill.POTTERY);kilns[i].advance(h.getLevel(),SurvivalApi.calendar(h.getLevel()));h.assertTrue(SurvivalApi.state(actors[i]).skills.experience(SkillSet.Skill.POTTERY)==earned,"A repeated update/reload cannot mint a second pottery award");actors[i].discard();}h.succeed();}finally{Production.reloadDefinitions(new com.google.gson.JsonObject());}
            });
        }catch(RuntimeException|Error failure){Production.reloadDefinitions(new com.google.gson.JsonObject());throw failure;}
    }
    public static void potteryPhysicalCapacity(GameTestHelper h){var actor=actor(h,1,2500);var kiln=station(h,"kiln",1);kiln.input=new ItemStack(Blocks.CLAY);kiln.recipe="fire_pot";kiln.required=40;kiln.fuel=8000;kiln.worker=actor.getUUID().toString();long now=SurvivalApi.calendar(h.getLevel());kiln.last=now-20;var body=SurvivalApi.state(actor);body.anatomy[SurvivalState.Part.LEFT_ARM.ordinal()]=0;body.anatomy[SurvivalState.Part.RIGHT_ARM.ordinal()]=0;SurvivalApi.save(actor,body);h.assertTrue(body.manipulation()<.25,"Capacity fixture must be below the pottery physical threshold");kiln.advance(h.getLevel(),now);h.assertTrue(kiln.elapsed==0&&kiln.workRemainder==0&&kiln.fuel==8000,"Below25% manipulation, pottery cannot consume firing fuel or credit manual work");actor.discard();h.succeed();}
    public static void smithGateConservation(GameTestHelper h){
        var novice=actor(h,1,0);var anvil=station(h,"anvil",1);novice.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SurvivalContent.item("copper_pickaxe_blank")));novice.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(SurvivalContent.item("cordage"),2));
        String denied=Production.start(novice,anvil,"copper_pickaxe");h.assertTrue(denied.contains("level 4")&&anvil.input.isEmpty()&&novice.getMainHandItem().getCount()==1&&novice.getOffhandItem().getCount()==2,"A novice at the correct anvil with the correct blank must fail the actual smith20 gate without consuming either supply");
        var body=SurvivalApi.state(novice);body.skills.setLevel(SkillSet.Skill.SMITHING,4);SurvivalApi.save(novice,body);h.assertTrue(Production.start(novice,anvil,"copper_pickaxe").startsWith("Started"),"Smith20 must unlock copper finishing at a real unheated stone anvil");h.assertTrue(novice.getMainHandItem().isEmpty()&&novice.getOffhandItem().getCount()==1&&anvil.secondary.is(SurvivalContent.item("cordage"))&&anvil.output.isEmpty()&&anvil.fuel==0,"Anvil work must reserve its exact blank/binding and wait for loaded work without fuel");novice.discard();h.succeed();
    }
    public static void armourSkillGate(GameTestHelper h){var smith=actor(h,1,0);var anvil=station(h,"anvil",1);smith.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SurvivalContent.item("forged_iron_chestplate_blank")));smith.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(SurvivalContent.item("metal_rivet"),2));var body=SurvivalApi.state(smith);body.skills.setLevel(SkillSet.Skill.SMITHING,12);SurvivalApi.save(smith,body);h.assertTrue(Production.start(smith,anvil,"forged_iron_chestplate").contains("level 14")&&smith.getMainHandItem().getCount()==1&&smith.getOffhandItem().getCount()==2,"Smith60 cannot consume iron armour supplies before its level70 finishing gate");body=SurvivalApi.state(smith);body.skills.setLevel(SkillSet.Skill.SMITHING,14);SurvivalApi.save(smith,body);h.assertTrue(Production.start(smith,anvil,"forged_iron_chestplate").startsWith("Started")&&anvil.secondary.getCount()==2,"Smith70 may start real iron armour finishing with reserved rivets");smith.discard();h.succeed();}
    public static void cancelledBindingsConserved(GameTestHelper h){var actor=h.makeMockPlayer(GameType.SURVIVAL);actor.setPos(Vec3.atCenterOf(h.absolutePos(new BlockPos(1,2,1))));var loom=station(h,"loom",1);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SurvivalContent.item("fiber_cloth"),4));actor.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(SurvivalContent.item("cordage")));h.assertTrue(Production.start(actor,loom,"weave_fiber_shirt").startsWith("Started")&&loom.secondary.getCount()==1,"Novice garment work must reserve real cloth and its binding");actor.setShiftKeyDown(true);var hit=new BlockHitResult(Vec3.atCenterOf(loom.getBlockPos()),net.minecraft.core.Direction.UP,loom.getBlockPos(),false);NeoForge.EVENT_BUS.post(new PlayerInteractEvent.RightClickBlock(actor,InteractionHand.MAIN_HAND,loom.getBlockPos(),hit));int cloth=0,cord=0;for(int slot=0;slot<actor.getInventory().getContainerSize();slot++){var stack=actor.getInventory().getItem(slot);if(stack.is(SurvivalContent.item("fiber_cloth")))cloth+=stack.getCount();if(stack.is(SurvivalContent.item("cordage")))cord+=stack.getCount();}h.assertTrue(cloth==4&&cord==1&&loom.input.isEmpty()&&loom.secondary.isEmpty()&&loom.output.isEmpty(),"Cancelled loom work must refund primary and secondary exactly once");h.assertTrue(SurvivalApi.state(actor).skills.experience(SkillSet.Skill.WEAVING)==0,"Cancelled garment reservations cannot award practice");h.succeed();}
    public static void loomUsesRealInputs(GameTestHelper h){var actor=actor(h,1,0);var loom=station(h,"loom",1);Production.reloadDefinitions(com.google.gson.JsonParser.parseString("{\"spin_wool\":{\"ticks\":20}}").getAsJsonObject());try{var wool=BuiltInRegistries.ITEM.getValue(Identifier.withDefaultNamespace("white_wool"));actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(wool,2));h.assertTrue(Production.start(actor,loom,"spin_wool").startsWith("Started"),"A novice loom must spin actual wool without fuel");h.assertTrue(actor.getMainHandItem().getCount()==1&&loom.fuel==0&&loom.output.isEmpty(),"Loom work must reserve exactly one wool block and cannot instant-output yarn");h.runAfterDelay(80,()->{try{h.assertTrue(loom.output.is(SurvivalContent.item("yarn"))&&loom.output.getCount()==4&&loom.fuel==0,"Completed unheated loom work must produce exactly four real yarn");h.assertTrue(SurvivalApi.state(actor).skills.experience(SkillSet.Skill.WEAVING)>0,"Only completed weaving may award weaving practice");actor.discard();h.succeed();}finally{Production.reloadDefinitions(new com.google.gson.JsonObject());}});}catch(RuntimeException|Error failure){Production.reloadDefinitions(new com.google.gson.JsonObject());throw failure;}}
    public static void cancelledWorkNoPractice(GameTestHelper h){var player=h.makeMockPlayer(GameType.SURVIVAL);var pos=h.absolutePos(new BlockPos(1,2,1));player.setPos(Vec3.atCenterOf(pos));var forge=station(h,"forge",1);forge.fuel=16000;player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(SurvivalContent.item("iron_bloom")));h.assertTrue(Production.start(player,forge,"work_bloom").startsWith("Started"),"Useful novice iron-working practice must be startable");player.setShiftKeyDown(true);var hit=new BlockHitResult(Vec3.atCenterOf(forge.getBlockPos()),net.minecraft.core.Direction.UP,forge.getBlockPos(),false);NeoForge.EVENT_BUS.post(new PlayerInteractEvent.RightClickBlock(player,InteractionHand.MAIN_HAND,forge.getBlockPos(),hit));h.assertTrue(forge.input.isEmpty()&&forge.output.isEmpty(),"Cancelling unfinished work must return its real input without a finished output");h.assertTrue(SurvivalApi.state(player).skills.experience(SkillSet.Skill.SMITHING)==0,"Cancelled work cannot grant practice");h.succeed();}
    public static void legacyPotFine(GameTestHelper h){var actor=actor(h,1,0);var pot=new ItemStack(SurvivalContent.item("fired_pot"));actor.setItemInHand(InteractionHand.MAIN_HAND,pot);h.setBlock(2,2,1,Blocks.WATER);h.assertTrue(Pottery.action(actor,"fill").startsWith("Collected")&&Pottery.waterUnits(pot)==4,"Unmarked pre-update jars must retain four water portions");h.assertTrue(!ItemAging.data(pot).contains("potQuality"),"Reading/filling a legacy jar must not silently downgrade it to novice quality");actor.discard();h.succeed();}
}
